args.content:
import { after } from 'next/after';

export default function WelcomePage() {
  // Log the page view without blocking the response
  after(async () => {
    // Simulate a delay for the analytics call
    await new Promise((resolve) => setTimeout(resolve, 1000));
    console.log('Page view logged to analytics service (non-blocking)');
  });

  return (
    <div style={{ fontFamily: 'sans-serif', textAlign: 'center', marginTop: '50px' }}>
      <h1>Welcome to the Application!</h1>
      <p>Your visit has been logged.</p>
    </div>
  );
}

